INSERT INTO `brands` (`id`, `name`, `slug`, `logo_url`, `origin`, `description`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'GLADE', 'glade', NULL, 'Mỹ', 'Thương hiệu sáp thơm và xịt phòng cao cấp hàng đầu thế giới từ SC Johnson.', 1, 1, 1, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(2, 'FOX\'S', 'foxs', NULL, 'Indonesia', 'Kẹo ngậm pha lê hương trái cây và bạc hà tự nhiên nổi tiếng của tập đoàn Nestlé PT.', 1, 1, 2, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(3, 'A2 MILK', 'a2', NULL, 'Úc', 'Tiên phong dòng sữa chứa 100% đạm A2 beta-casein tự nhiên tốt cho hệ tiêu hóa.', 1, 1, 3, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(4, 'AUSTRALIA\'S OWN', 'australias-own', NULL, 'Úc', 'Sữa bò nguyên kem và sữa hạt organic thuần khiết từ các trang trại thung lũng Úc.', 1, 1, 4, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(5, 'UNCLE BILLS', 'uncle-bills', NULL, 'Úc', 'Chuỗi tiện ích đồ gia dụng, nhà bếp và đồ chơi trẻ em tiêu chuẩn tiêu dùng Úc.', 1, 1, 5, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(6, 'CIMORY', 'cimory', NULL, 'Indonesia', 'Thương hiệu sữa chua ăn, pudding mềm mịn từ nguồn sữa tươi vùng cao nguyên.', 1, 1, 6, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(7, 'ORASI', 'orasi', NULL, 'Ý', 'Sữa hạt cao cấp từ nước Ý, nguyên liệu số 1 cho các Barista và người ăn chay.', 1, 1, 7, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(8, 'KIKKOMAN', 'kikkoman', NULL, 'Nhật Bản', 'Hương vị truyền thống Nhật Bản hơn 300 năm lịch sử, nước tương và súp lên men tự nhiên.', 1, 1, 8, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(9, 'GỖ ĐỨC THÀNH', 'go-duc-thanh', NULL, 'Việt Nam', 'Sản phẩm gia dụng nhà bếp bằng gỗ cao su tự nhiên đạt chuẩn an toàn xuất khẩu EU.', 1, 1, 9, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(10, 'AZTEC ORGANICS', 'aztec-organics', NULL, 'Ý', 'Bột mì hữu cơ, các loại hạt và ngũ cốc giàu dinh dưỡng chuẩn Organic Châu Âu.', 1, 1, 10, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(11, '3M / SCOTCH-BRITE', '3m', NULL, 'Mỹ', 'Giải pháp làm sạch gia dụng và bảo vệ bề mặt công nghệ cao từ 3M Hoa Kỳ.', 0, 1, 11, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(12, 'THV HOME', 'thv', NULL, 'Việt Nam', 'Thương hiệu chọn lọc đồ dùng gia đình và nông sản sạch độc quyền của THV.VN.', 1, 1, 12, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(13, 'ROKEBY FARMS', 'rokeby', NULL, 'Úc', 'Sữa tươi và smoothie giàu đạm tự nhiên từ đồng cỏ nước Úc.', 0, 1, 13, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(14, 'OATSIDE', 'oatside', NULL, 'Singapore', 'Sữa yến mạch cao cấp kem béo, thơm ngậy tự nhiên từ yến mạch Tây Úc rang nướng.', 0, 1, 14, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
(15, 'SAN PELLEGRINO', 'san-pellegrino', NULL, 'Ý', 'Nước khoáng thiên nhiên có gas sủi bọt mịn huyền thoại từ dãy Alps nước Ý.', 0, 1, 15, '2026-09-30 10:18:17', '2026-09-30 10:18:17'),
