('hg-cache-site_system_setting', 'O:18:\"App\\Models\\Setting\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:8:\"settings\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:5:{s:2:\"id\";i:1;s:16:\"general_settings\";s:621:\"{\"email\": {\"smtp_host\": \"xxxxxx\", \"smtp_port\": \"xxxxxxx\", \"smtp_user\": \"resend\", \"sender_email\": \"ecom@asxh.org.vn\", \"contact_email\": \"ecom@asxh.org.vn\", \"smtp_password\": \"xxxxxxxxxxx\"}, \"system\": {\"is_active\": true}, \"payment\": {\"bank_name\": \"Ngân hàng TMCP Quốc Tế Việt Nam (VIB)\", \"account_name\": \"CONG TY CP ĐẦU TƯ & XÚC TIẾN THƯƠNG MẠI DOANH NGHIỆP VIỆT\", \"account_number\": \"475475\"}, \"scripts\": {\"body\": null, \"footer\": null, \"header\": null}, \"security\": {\"block_copy\": false, \"block_inspect\": false}, \"site_icon\": \"01a17821-fc18-702c-9e3c-5c67ef6fc9a8\", \"site_name\": \"DOANH NGHIỆP VIỆT\"}\";s:18:\"interface_settings\";s:25937:\"{\"blog\": {\"per_page\": 6, \"author_bio\": \"Ban Biên tập DNV là Quản trị viên Website và Các Thành viên Phòng KD - Cty DNV\", \"meta_image\": \"01a1ccd4-d97e-7134-ae56-6261d33e0d6d\", \"meta_title\": \"Các bài viết về Hoạt động Thương mại\", \"author_name\": \"Ban Biên tập DNV\", \"author_role\": \"Ban Biên tập DNV\", \"meta_keywords\": \"blog ẩm thực, mẹo nấu ăn, dinh dưỡng lành mạnh, kiến thức, kỹ năng, thực phẩm sạch, online, ecommerce\", \"popular_title\": \"Bài Viết Nổi Bật\", \"meta_description\": \"Kinh doanh, marketing, brand activation, sampling, chào bán hàng, giao hàng, đào tạo, kpi, lương thưởng,\"}, \"cart\": {\"title\": \"Mua số lượng nhiều được giảm miễn phí ship\", \"meta_image\": \"01a1af79-253c-715b-b77e-f77fb63b8e36\", \"meta_title\": \"Giỏ