INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `image_url`, `icon`, `description`, `is_active`, `is_featured`, `sort_order`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`) VALUES
(1, NULL, 'Bánh & Snack', 'banh', '01a186d0-17f5-7037-a74a-846415d8a0f2', 'fa-solid fa-cookie-bite', 'Các loại bánh quy, bánh xốp, bánh bông lan, bánh gạo, bánh snack thơm ngon, chất lượng cao.', 1, 1, 1, 'Bánh & Snack | DOANH NGHIỆP VIỆT', 'Các loại bánh quy, bánh xốp, bánh bông lan, bánh gạo, bánh snack thơm ngon, chất lượng cao.', NULL, '2026-10-26 05:50:50', '2026-11-11 09:33:45'),
(7, NULL, 'Kẹo - Sô cô la', 'keo', '01a186d3-fe39-72f1-bee4-e58f62a29c78', 'fa-solid fa-candy-cane', 'Kẹo dẻo, kẹo cứng, chocolate cao cấp, kẹo ngậm và kẹo mềm đa dạng hương vị.', 1, 1, 2, 'Kẹo - Sô cô la | DOANH NGHIỆP VIỆT', 'Kẹo dẻo, kẹo cứng, chocolate cao cấp, kẹo ngậm và kẹo mềm đa dạng hương vị.', NULL, '2026-10-26 05:50:50', '2026-11-11 09:33:45'),
(12, NULL, 'Nước uống', 'nuoc-uong', '01a186d4-7f93-7292-af80-198f5693a17a', 'fa-solid fa-bottle-water', 'Nước khoáng tinh khiết, nước ngọt giải khát, nước ép trái cây, trà, cà phê và sữa dinh dưỡng.', 1, 1, 3, 'Nước uống | DOANH NGHIỆP VIỆT', 'Nước khoáng tinh khiết, nước ngọt giải khát, nước ép trái cây, trà, cà phê và sữa dinh dưỡng.', NULL, '2026-10-26 05:50:50', '2026-11-11 09:33:45'),
(19, NULL, 'Ngũ cốc', 'ngu-coc', '01a186d4-fe0d-720e-8e07-ec9c695fa2ee', 'fa-solid fa-seedling', 'Gạo sạch, đậu hạt, trái cây tươi sạch, rau củ quả VietGAP và nông sản sấy khô tự nhiên.', 1, 1, 4, 'Ngũ cốc | DOANH NGHIỆP VIỆT', 'Gạo sạch, đậu hạt, trái cây tươi sạch, rau củ quả VietGAP và nông sản sấy khô tự nhiên.', NULL, '2026-10-26 05:50:50', '2026-11-18 02:56:03'),
(25, NULL, 'Snack Thủy hải sản', 'thuy-hai-san', '01a186d5-9654-7370-81c1-456fb9df01b9', 'fa-solid fa-fish', 'Ăn vặt Thủy hải sản đồ khô và hải sản chế biến sẵn đóng hộp đạt chuẩn ATTP.', 1, 1, 5, 'Snack Thủy hải sản | DOANH NGHIỆP VIỆT', 'Thủy hải sản tươi sống, hải sản đông lạnh, đồ khô và hải sản chế biến sẵn đóng hộp đạt chuẩn ATTP.', NULL, '2026-10-26 05:50:50', '2026-11-11 09:33:45'),
(30, NULL, 'Trái cây sấy', 'trai-cay-say', '01a186d6-96b7-72b6-8c65-d2c0b2d6383b', 'fa-solid fa-wheat-awn', 'Các loại trái cây hay rau củ sấy giòn sấy dẻo ăn vặt', 1, 1, 6, 'Trái cây sấy | DOANH NGHIỆP VIỆT', 'Yến mạch, ngũ cốc ăn sáng, bột ngũ cốc nguyên cám, Granola và các loại hạt dinh dưỡng.', NULL, '2026-10-26 05:50:50', '2026-11-18 02:56:03'),
(35, NULL, 'Nui mì bún miến', 'nui-mi-bun-mien', '01a186d7-3a1f-7200-80b5-194e3b499bae', 'fa-solid fa-bowl-food', 'Mì ăn liền, bún khô, miến dong, hủ tiếu, nui, mì Ý pasta và bánh tráng các loại.', 1, 1, 7, 'Nui mì bún miến | DOANH NGHIỆP VIỆT', 'Mì ăn liền, bún khô, miến dong, hủ tiếu, nui, mì Ý pasta và bánh tráng các loại.', NULL, '2026-10-26 05:50:50', '2026-11-11 09:33:45'),
(41, NULL, 'Gia vị', 'gia-vi', '01a186d8-3ba3-70a1-b2f2-36cda7084fe6', 'fa-solid fa-mortar-pestle', 'Nước mắm, nước tương, dầu ăn, đường, muối, hạt nêm, tương ớt, sốt ướp và gia vị nấu ăn cao cấp.', 1, 1, 8, 'Gia vị | DOANH NGHIỆP VIỆT', 'Nước mắm, nước tương, dầu ăn, đường, muối, hạt nêm, tương ớt, sốt ướp và gia vị nấu ăn cao cấp.', NULL, '2026-10-26 05:50:50', '2026-11-11 09:33:45'),
(48, NULL, 'Mỹ phẩm', 'my-pham', '01a186d8-b7dc-70ea-92f3-1dd1c8773417', 'fa-solid fa-spa', 'Mỹ phẩm dưỡng da, kem chống nắng, son môi, đồ trang điểm, mặt nạ và serum chính hãng.', 1, 1, 9, 'Mỹ phẩm | DOANH NGHIỆP VIỆT', 'Mỹ phẩm dưỡng da, kem chống nắng, son môi, đồ trang điểm, mặt nạ và serum chính hãng.', NULL, '2026-10-26 05:50:50', '2026-11-11 09:33:45'),
(54, NULL, 'Hóa mỹ phẩm', 'hoa-my-pham', '01a186d9-5bdd-72f3-8c40-d10480a4bbbd', 'fa-solid fa-pump-soap', 'Sữa tắm, dầu gội, dầu xả, kem đánh răng, nước súc miệng, khử mùi và vệ sinh cá nhân.', 1, 1, 10, 'Hóa mỹ phẩm | DOANH NGHIỆP VIỆT', 'Sữa tắm, dầu gội, dầu xả, kem đánh răng, nước súc miệng, khử mùi và vệ sinh cá nhân.', NULL, '2026-10-26 05:50:50', '2026-11-11 09:33:45'),
(61, NULL, 'Dụng cụ gia đình', 'do-dung-gia-dinh', '01a186da-b88d-733a-ba8c-3aa9385b8a4b', 'fa-solid fa-house-chimney', 'Nước giặt xả, nước rửa chén, lau sàn, giấy vệ sinh, túi rác và vật dụng gia đình tiện ích.', 1, 1, 11, 'Dụng cụ gia đình | DOANH NGHIỆP VIỆT', 'Nước giặt xả, nước rửa chén, lau sàn, giấy vệ sinh, túi rác và vật dụng gia đình tiện ích.', NULL, '2026-10-26 05:50:50', '2026-11-11 09:33:45'),
(68, NULL, 'Phụ kiện Công nghệ', 'sp-cong-nghe', '01a186c0-27b1-715b-b555-e2008d0a49d5', NULL, 'Các sản phẩm dành cho điện thoại thông minh, máy tính, laptop', 1, 0, 0, 'SP Công nghệ | DOANH NGHIỆP VIỆT', NULL, NULL, '2026-10-29 04:31:46', '2026-11-13 02:16:40'),
(70, NULL, 'Văn phòng phẩm', 'van-phong-pham', '01a186cc-961c-7005-95ab-6e5291f92177', NULL, 'Văn phòng phẩm dùng cho văn phòng - gia đình - học tập - nữ công - trang trí', 1, 0, 0, 'Văn phòng phẩm | DOANH NGHIỆP VIỆT', NULL, NULL, '2026-10-29 04:35:03', '2026-11-11 09:33:45'),
