INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name`, `slug`, `description`, `content`, `base_price`, `sale_price`, `sku`, `unit`, `weight`, `image_url`, `badge`, `badge_color`, `discount_label`, `is_active`, `is_featured`, `is_flash_sale`, `view_count`, `sold_count`, `stock_quantity`, `stock_warning`, `sort_order`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`, `gallery`) VALUES
(301, NULL, NULL, 'Nước chấm cá cơm than - Việt Nhĩ - 800 ml QC15', 'viet-nhi-nuoc-cham-ca-com-than-800-ml-qc15', 'Nước chấm cá cơm than - Việt Nhĩ - 800 ml QC15', '<p><strong>Nước chấm cá cơm than - Việt Nhĩ - 800 ml QC15</strong> là sản phẩm chất lượng cao đến từ thương hiệu <strong>CÔNG TY CP TẬP ĐOÀN HƯNG VIỆT</strong>, sở hữu hương vị mặn mà đậm đà hòa quyện cùng mùi thơm đặc trưng từ nguồn cá cơm than tự nhiên. Sản phẩm đóng chai dung tích lớn tiện lợi, thích hợp làm gia vị nêm nếm và nước chấm tròn vị cho mọi bữa cơm gia đình, học sinh, sinh viên và các gian bếp kinh doanh ăn uống.</p><p><strong>Đặc điểm nổi bật:</strong></p><p>Thành phần cá cơm than tự nhiên</p><p>Hương vị thơm ngon bắt miệng. Vị mặn dịu hài hòa cùng hậu vị ngọt thanh tự nhiên, dậy mùi thơm hấp dẫn giúp món ăn thêm phần đậm đà mà không gây gắt.</p><p>Dung tích 800ml vừa vặn, tiết kiệm, dễ dàng bảo quản và đáp ứng tốt nhu cầu nấu nướng, pha chế nước chấm hằng ngày của gia đình.</p><p><strong>Thông tin sản phẩm:</strong></p><p>Tên sản phẩm: Nước chấm cá cơm than - Việt Nhĩ - 800 ml QC15</p><p>Thương hiệu: Công ty CP Tập Đoàn Hưng Việt</p><p>Dung tích: 800ml / chai</p><p>Hướng dẫn sử dụng: Dùng để nêm hoặc làm nước chấm. Đậy kín sau khi dùng để chứa hương vị.</p><p>#doanhnghiepviet #ecommerce #tmdt #hcmc #hangtieudung #vietnhi #nuocchamcacomthan #nuocmamcacom #giavibep</p>', 16000.00, 16000.00, 'B0001', 'Chai', '800 ml', '01a1bea1-ef5e-7268-943d-7811240f6329', NULL, NULL, NULL, 1, 0, 0, 15, 1, 9999, NULL, 0, NULL, NULL, NULL, '2026-11-09 04:46:41', '2026-11-15 22:27:51', NULL),
(302, NULL, NULL, 'Nước mắm cốt nhĩ 35% - Việt Nhĩ - 500 ml (Chai Thủy tinh)', 'viet-nhi-nuoc-mam-cot-nhi-35-500-ml-thuy-tinh', 'Nước mắm cốt nhĩ 35% - Việt Nhĩ - 500 ml (Chai Thủy tinh)', '<p><strong>Nước mắm cốt nhĩ 35% - Việt Nhĩ - 500 ml (Chai Thủy tinh)</strong> là sản phẩm chất lượng cao đến từ thương hiệu <strong>CÔNG TY CP TẬP ĐOÀN HƯNG VIỆT</strong>.</p><p>Được làm từ nước mắm cá cơm nguyên chất (35%), sản xuất theo quy trình truyền thống với tỷ lệ ướp chượp 3 cá:1 muối. Kết hợp với công thức hoàn hảo từ nhãn hàng Việt Nhĩ, tạo ra dòng sản phẩm tuyệt vời với vị ngon hài hoà.</p><h3>Thành phần chính</h3><p>Nước mắm cá cơm nguyên chất, nước, muối, chất ổn định độ acid, ...</p><h3>Hướng dẫn sử dụng</h3><p>Dùng để chấm ăn sống hoặc ướp tẩm thực phẩm khi chế biến, làm tăng hương vị món ăn thêm đậm đà</p><p>#doanhnghiepviet #ecommerce #tmdt #hcmc #hangtieudung #vietnhi #nuocmam</p>', 40000.00, 40000.00, 'B0002', 'Chai', '500 ml', '01a1bea8-80be-734b-b57b-3d36e769d324', NULL, NULL, NULL, 1, 0, 0, 10, 0, 10000, NULL, 0, NULL, NULL, NULL, '2026-11-09 04:54:13', '2026-11-17 21:39:14', NULL),
(303, NULL, NULL, 'Việt Nhĩ nước mắm cá cơm than 750 ml', 'viet-nhi-nuoc-mam-ca-com-than-750-ml', 'Việt Nhĩ nước mắm cá cơm than 750 ml', '<p><strong>NƯỚC MẮM CÁ CƠM THAN VIỆT NHĨ 12N – CHAI 750ML</strong></p><p>Gia vị quen thuộc cho gian bếp Việt!</p><p>Nước mắm cá cơm than Việt Nhĩ 12N với dung tích 750ml, thích hợp sử dụng trong chế biến các món ăn hằng ngày. Sản phẩm có thể dùng để nêm canh, kho cá, kho thịt, ướp thực phẩm hoặc pha nước chấm chua ngọt.</p><p>Một lựa chọn gia vị tiện dụng cho bữa cơm gia đình và các hoạt động kinh doanh ăn uống.</p><p><strong>Quy cách:</strong> Chai 750ml.</p><p><strong>Công dụng:</strong> Nêm nếm – Ướp thực phẩm – Pha nước chấm.</p><p>#doanhnghiepviet #ecommerce #tmdt #hcmc #hangtieudung #vietnhi #nuocmam</p>', 38000.00, 38000.00, 'B0003', 'Chai', '750 ml', '01a1beb6-0cd3-73d9-bb4b-9e614ae264d5', NULL, NULL, NULL, 1, 0, 0, 8, 0, 10000, NULL, 0, NULL, NULL, NULL, '2026-11-09 05:09:06', '2026-11-15 14:20:50', NULL),
(304, NULL, NULL, 'Gạo Hữu cơ Sinh học - Yến Ngọc 5 kg', 'gao-huu-co-sinh-hoc-yen-ngoc-5-kg', 'GẠO HỮU CƠ SINH HỌC NGỌC YẾN:\n\n(Dành cho vào phân khúc cao cấp, quan tâm sức khỏe gia đình, tiêu chuẩn quốc tế)\nBữa cơm an lành - sức khỏe bền vững cho gia đình với gạo hữu cơn sinh học Ngọc Yến', '<p><strong><u>GẠO HỮU CƠ SINH HỌC NGỌC YẾN:</u></strong></p><p>(Dành cho vào phân khúc cao cấp, quan tâm sức khỏe gia đình, tiêu chuẩn quốc tế)</p><p style=\"text-align: center;\"><strong>Bữa cơm an lành - sức khỏe bền vững cho gia đình với gạo hữu cơn sinh học Ngọc Yến</strong></p><p style=\"text-align: justify;\">- Một bữa cơm ngon không chỉ nằm ở hương vị, mà còn ở sự an tâm tuyệt đối cho sức khỏe của những người thân yêu. Đó là lý do <strong>Gạo Hữu Cơ Sinh Học Ngọc Yến</strong> luôn là sự lựa chọn hàng đầu của các bà nội trợ thông thái.</p><p style=\"text-align: justify;\">1. Tại sao Gạo Ngọc Yến được nhiều gia đình tin dùng?</p><p style=\"text-align: justify;\"> <strong>Canh tác hữu cơ sinh học:</strong> Quy trình chuẩn sạch từ đồng ruộng đến bàn ăn, hoàn toàn thân thiện với môi trường và an toàn cho sức khỏe.</p><p style=\"text-align: justify;\"><strong>Hạt gạo tinh túy:</strong> Căng bóng, đậm vị ngọt tự nhiên, dẻo mềm và thơm lừng góc bếp.</p><p style=\"text-align: justify;\"><strong>Đạt chuẩn quốc tế HALAL:</strong> Minh chứng cho quy trình sản xuất nghiêm ngặt, đáp ứng những tiêu chuẩn khắt khe nhất về an toàn vệ sinh thực phẩm. Mang tinh hoa thiên nhiên vào từng bát cơm nhà bạn</p><p style=\"text-align: justify;\"><strong>Cam kết chất lượng: </strong>Đóng gói tiêu chuẩn, giúp bảo quản gạo luôn tươi mới, chống mối mọt và giữ trọn hương vị gốc.</p><p style=\"text-align: justify;\">#doanhnghiepviet #ecommerce #tmdt #hcmc #hangtieudung #gao #ngocyen #luongthuc</p>', 118000.00, 118000.00, 'B0004', 'Túi', '5 kg', '01a1c8bc-029e-7247-8995-b07215d711b8', NULL, NULL, NULL, 1, 0, 0, 8, 0, 10000, NULL, 0, NULL, NULL, NULL, '2026-11-09 06:03:03', '2026-11-15 14:24:03', NULL),
(305, NULL, NULL, 'Chao môn DNV 180 gr', 'chao-mon-dnv-180-gr', 'Chao môn_180g là sản phẩm chất lượng cao đến từ thương hiệu CÔNG TY TNHH THỰC PHẨM MINH NHẬT ĐÀ LẠT', '<p><strong>Chao môn 180g</strong> là sản phẩm chất lượng cao đến từ thương hiệu<strong> Công ty TNHH Thực phẩm Minh Nhật Đà Lạt</strong>, sở hữu chất chao mềm béo tự nhiên hòa quyện cùng hương thơm đặc trưng từ quá trình lên men truyền thống. Sản phẩm đóng hũ nhỏ gọn tiện lợi, phù hợp cho cả người ăn chay lẫn ăn mặn, thích hợp dùng làm nước chấm, gia vị tẩm ướp hoặc chế biến món ăn đậm đà cho mọi bữa cơm gia đình, học sinh, sinh viên và dân văn phòng.</p><p><strong>Đặc điểm nổi bật:</strong></p><ol start=\"1\"><li><p>Lên men tự nhiên, chay mặn đều dùng được: Chế biến từ khoai môn chọn lọc qua quy trình lên men tự nhiên chuẩn mực của Thực phẩm Minh Nhật Đà Lạt, giàu dinh dưỡng và an toàn cho sức khỏe.</p></li><li><p>Hương vị mềm béo bắt miệng: Chất chao sánh mịn, béo bùi hài hòa cùng vị mặn ngọt dịu nhẹ, dễ ăn và không gây ngấy.</p></li><li><p>Quy cách hũ 180g tiện lợi: Đóng hũ 180g vừa vặn, dễ dàng sử dụng, bảo quản và đa năng trong gian bếp từ chấm rau củ, thịt nướng đến tẩm ướp, xào nấu.</p></li></ol><p><strong>Thông tin sản phẩm:</strong></p><ul><li><p>Tên sản phẩm: Chao Môn</p></li><li><p>Thương hiệu: Công ty TNHH Thực phẩm Minh Nhật Đà Lạt</p></li><li><p>Trọng lượng: 180g / hũ</p></li><li><p>Hướng dẫn sử dụng: Dùng chấm trực tiếp với rau luộc, thịt nướng, lẩu; pha chế nước chấm (thêm đường, ớt, tỏi, chanh) hoặc dùng làm gia vị ướp thực phẩm, xào rau củ. Đậy kín nắp sau khi sử dụng.</p></li></ul><p>#doanhnghiepviet #ecommerce #tmdt #hcmc #hangtieudung #chaomon #minhnhatdalat #chaoanchay #giavibep</p>', 18000.00, 18000.00, 'B0005', 'Hũ', '180 gr', '01a1bf0c-7642-70dd-a1c6-68d90069cfcd', NULL, NULL, NULL, 1, 0, 0, 8, 0, 10000, NULL, 0, NULL, NULL, NULL, '2026-11-09 06:42:44', '2026-11-17 20:46:39', NULL),
