(1, '{\"ghn\": {\"api_url\": \"https://online-gateway.ghn.vn/shiip/public-api/\", \"shop_id\": \"6665569\", \"api_token\": \"4366d497-afec-11f1-8cda-3204dc9bded5\", \"is_active\": true, \"from_ward_code\": \"21201\", \"from_district_id\": 1454, \"from_province_id\": 202}, \"email\": {\"smtp_host\": \"xxxxxx\", \"smtp_port\": \"xxxxxxx\", \"smtp_user\": \"resend\", \"sender_email\": \"ecom@asxh.org.vn\", \"contact_email\": \"ecom@asxh.org.vn\", \"smtp_password\": \"xxxxxxxxxxx\"}, \"system\": {\"is_active\": true}, \"payment\": {\"bank_name\": \"Ngân hàng TMCP Quốc Tế Việt Nam (VIB)\", \"account_name\": \"CONG TY CP ĐẦU TƯ & XÚC TIẾN THƯƠNG MẠI DOANH NGHIỆP VIỆT\", \"account_number\": \"475475\"}, \"scripts\": {\"body\": null, \"footer\": null, \"header\": null}, \"security\": {\"block_copy\": false, \"block_inspect\": false}, \"site_icon\": \"01a17821-fc18-702c-9e3c-5c67ef6fc9a8\", \"site_name\": \"DOANH NGHIỆP VIỆT\"}', '{\"blog\": {\"per_page\": 6, \"author_bio\": \"Ban Biên tập DNV là Quản trị viên Website và Các Thành viên Phòng KD - Cty DNV\", \"meta_image\": \"01a1ccd4-d97e-7134-ae56-6261d33e0d6d\", \"meta_title\": \"Các bài viết về Hoạt động Thương mại\", \"author_name\": \"Ban Biên tập DNV\", \"author_role\": \"Ban Biên tập DNV\", \"meta_keywords\": \"blog ẩm thực, mẹo nấu ăn, dinh dưỡng lành mạnh, kiến thức, kỹ năng, thực phẩm sạch, online, ecommerce\", \"popular_title\": \"Bài Viết Nổi Bật\", \"meta_description\": \"Kinh doanh, marketing, brand activation, sampling, chào bán hàng, giao hàng, đào tạo, kpi, lương thưởng,\"}, \"cart\": {\"title\": \"Mua số lượng nhiều được giảm miễn phí ship\", \"meta_image\": \"01a1af79-253c-715b-b77e-f77fb63b8e36\", \"meta_title\": \"Giỏ Hàng Mua Sắm - DNV\", \"empty_title\": \"Giỏ hàng của bạn đang trống\", \"trust_badges\": [{\"icon\": \"fa-solid fa-box-archive\", \"title\": \"Đóng gói cẩn thận\", \"description\": \"Cam kết bảo quản giữ trọn độ tươi sống và dưỡng chất đến tận tay bạn.\"}, {\"icon\": \"fa-solid fa-truck-fa